# translated into topology, graph theory, lattices, singularities.  ES5(p) := exists t,u,v>=2, tuv-u-v=p, (A/p)=-1,
# A=tu-1 (sufficient for ES(p); slot lemma: <=> 4 | one of t,u,v,tu-1,tv-1).
